class RunTests {
  public void runTests() {
    Object[][] tests = {
        // Example from book
        { new String[] {
            "...X.O",
            "OX.X..",
            "...X..",
            ".X....",
            "XOX.XX" },
            new int[][] {
                { 1, 2, 3, -1, 1, 0 },
                { 0, -1, 4, -1, 2, 1 },
                { 1, 2, 3, -1, 3, 2 },
                { 2, -1, 4, 5, 4, 3 },
                { -1, 0, -1, 6, -1, -1 } } },
        // Single exit
        { new String[] {
            "...",
            ".O.",
            "..." },
            new int[][] {
                { 2, 1, 2 },
                { 1, 0, 1 },
                { 2, 1, 2 } } },
        // Multiple exits
        { new String[] {
            "O.O",
            "...",
            "O.O" },
            new int[][] {
                { 0, 1, 0 },
                { 1, 2, 1 },
                { 0, 1, 0 } } },
        // Walls blocking direct paths
        { new String[] {
            "O.X.",
            "XX..",
            "...O" },
            new int[][] {
                { 0, 1, -1, 2 },
                { -1, -1, 2, 1 },
                { 3, 2, 1, 0 } } },
        // Single cell
        { new String[] { "O" },
            new int[][] { { 0 } } }
    };

    ExitDistances solution = new ExitDistances();
    for (Object[] test : tests) {
      String[] mazeArray = (String[]) test[0];
      List<String> maze = Arrays.stream(mazeArray).collect(Collectors.toList());
      int[][] want = (int[][]) test[1];
      int[][] got = solution.solve(maze);
      if (!Arrays.deepEquals(got, want)) {
        throw new RuntimeException(String.format(
            "\nsolve(%s): got: %s, want: %s\n",
            maze, Arrays.deepToString(got), Arrays.deepToString(want)));
      }
    }
  }
}

public class Solution {
  public static void main(String[] args) {
    new RunTests().runTests();
  }
}
